const assert=require("node:assert/strict");
const fs=require("node:fs");
const page=fs.readFileSync("src/app/page.tsx","utf8");
const start=page.indexOf("const comparableCart = useMemo(() => {");
const end=page.indexOf("\n  const chainResults = useMemo",start);
const chainEnd=page.indexOf("\n  const ",end+20);
const guard=page.slice(start,end);
const chain=page.slice(end,chainEnd>end?chainEnd:end+2700);
assert.match(guard,/cart\.filter\(isComparisonEligibleV797\)/);
assert.match(chain,/const sList = comparableCart/);
assert.match(chain,/const kList = comparableCart/);
assert.match(chain,/const sTotal = visibleSListV804\.reduce/);
assert.match(chain,/const kTotal = visibleKListV804\.reduce/);
const normal={id:"milk",source:"normal",price:2.5,quantity:1};
const weight={id:"loose-fruit",source:"offer",price:0,quantity:1,product:{ziiplyWeightOffer:true,ziiplyPricePendingWeight:true,comparisonPrice:4.99,comparisonPriceUnit:"kg"}};
const fixedOffer={id:"bucket",source:"offer",price:5,quantity:1};
const eligible=x=>String(x.source||"").toLowerCase()!=="offer";
const cart=[normal,weight,fixedOffer],comparison=cart.filter(eligible);
assert.deepEqual(comparison.map(x=>x.id),["milk"]);
const matches={milk:{price:2.5,quantity:1}};
const total=comparison.map(x=>matches[x.id]).reduce((sum,m)=>sum+m.price*m.quantity,0);
assert.equal(total,2.5);
assert.deepEqual([weight,fixedOffer].filter(eligible),[]);
console.log("PASS mixed basket: only normal items enter S/K comparison, both Gösta offer types remain outside");
console.log("PASS chainResults source uses filtered comparableCart for both S and K totals");
